int main() {
    // One day of card transactions, in cents. All of them are debits.
    std::vector<int> deltas{-450, -120, -900, -60};

    int largest = std::accumulate(
        deltas.begin(), deltas.end(), 0,
        [](int best, int delta) { return std::max(best, delta); });

    int smallest = std::accumulate(
        deltas.begin(), deltas.end(), deltas.front(),
        [](int worst, int delta) { return std::min(worst, delta); });

    std::cout << largest << ' ' << smallest << '\n';
}

