#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

struct Ticket {
    int priority;
    std::string tag;
};

void enqueue(std::vector<Ticket>& queue, Ticket ticket) {
    auto at = std::ranges::upper_bound(
        queue, ticket.priority, {}, &Ticket::priority);
    queue.insert(at, std::move(ticket));
}

int main() {
    std::vector<Ticket> queue;
    enqueue(queue, {2, "a"});
    enqueue(queue, {1, "b"});
    enqueue(queue, {2, "c"});
    enqueue(queue, {1, "d"});

    for (const Ticket& ticket : queue) {
        std::cout << ticket.priority << ticket.tag << ' ';
    }
    std::cout << '\n';
}

