#include <algorithm>
#include <string>
#include <tuple>
#include <vector>

struct Entry {
    std::string handle;
    int score;
    int seconds;
};

void rank(std::vector<Entry>& board) {
    // Lexicographic comparison of two tuples is irreflexive and transitive
    // whenever each element comparison is, and < on int and on std::string
    // both are -- so this relation is a strict weak ordering by
    // construction, with no case analysis to get wrong. Flipping only the
    // score fields between the two tuples reverses that one key.
    // Writing >= anywhere would make compare(a, a) true and hand sort
    // undefined behaviour.
    std::ranges::sort(board, [](const Entry& lhs, const Entry& rhs) {
        return std::tie(rhs.score, lhs.seconds, lhs.handle)
             < std::tie(lhs.score, rhs.seconds, rhs.handle);
    });
}

#include <algorithm>
#include <cstddef>
#include <vector>

double median(std::vector<double> samples, double fallback) {
    if (samples.empty()) {
        return fallback;
    }

    const std::size_t count = samples.size();
    const auto middle =
        samples.begin() + static_cast<std::ptrdiff_t>(count / 2);

    // Average O(N): places one element at its final rank and partitions
    // around it. Neither side is ordered afterwards -- only bounded.
    std::ranges::nth_element(samples, middle);
    const double upper = *middle;

    if (count % 2 == 1) {
        return upper;
    }

    // Even size needs the other middle value too. Everything in
    // [begin, middle) compares no greater than *middle, so the value we
    // want is simply the largest of that partition: one more linear scan,
    // no second selection and no sort.
    const double lower = *std::ranges::max_element(samples.begin(), middle);
    return (lower + upper) / 2.0;
}

#include <algorithm>
#include <cstddef>
