// Precondition: `starts` is sorted ascending. Nothing here checks that,
// and a violation is undefined behaviour rather than a wrong answer.
std::ptrdiff_t count_in_window(const std::vector<int>& starts,
                               int from, int until) {
    const auto first = std::ranges::lower_bound(starts, from);

    // Both edges use lower_bound because the window is half-open: an
    // appointment starting exactly at `until` is outside it. Searching
    // only [first, end) keeps the second probe sequence inside the part
    // of the range that can still qualify.
    const auto last = std::ranges::lower_bound(first, starts.end(), until);

    return last - first;
}

#include <algorithm>
#include <cstddef>
#include <string>
#include <vector>

struct Step {
    std::string name;
    bool ready;
};

std::size_t hoist_ready(std::vector<Step>& steps) {
    // Plain partition would satisfy the grouping but is free to scramble
    // each group; preserving the original order inside both groups is
    // stable_partition's contract, paid for with a possible temporary
    // buffer allocation.
    auto blocked = std::ranges::stable_partition(steps, &Step::ready);

    // The algorithm returns the *second* group, so its begin() is the
    // boundary -- the count is already in hand, with no second pass.
    return static_cast<std::size_t>(blocked.begin() - steps.begin());
}

#include <cstdint>
#include <functional>
#include <numeric>
#include <span>
#include <stdexcept>

std::int64_t basket_total(std::span<const std::int32_t> unit_price_cents,
                          std::span<const std::int32_t> quantities) {
    if (unit_price_cents.size() != quantities.size()) {
        throw std::invalid_argument{"basket arrays disagree in length"};
    }

    return std::transform_reduce(
        unit_price_cents.begin(), unit_price_cents.end(),
        quantities.begin(),
        std::int64_t{0},
        std::plus<>{},
        [](std::int32_t price, std::int32_t quantity) {
            // Cast first: price * quantity would be evaluated in int and
            // could overflow before anything widened it, and signed
            // overflow is undefined behaviour rather than a wrap. The
            // std::int64_t initial value keeps the running sum wide too.
            return static_cast<std::int64_t>(price) * quantity;
        });
}

#include <algorithm>
#include <iterator>
#include <string>
#include <vector>

using Manifest = std::vector<std::string>;

// Precondition on both functions: each input is sorted under the same
// ordering the output is expected in. Sorted-set algorithms trust that
// and never verify it.
Manifest merge_manifests(const Manifest& last_night,
                         const Manifest& tonight) {
    Manifest all;
    // A union is at most both inputs combined; reserving that bound turns
    // the growth of the destination into one allocation.
    all.reserve(last_night.size() + tonight.size());

    std::ranges::set_union(last_night, tonight, std::back_inserter(all));
    return all;
}

Manifest only_tonight(const Manifest& last_night,
                      const Manifest& tonight) {
    Manifest added;
    std::ranges::set_difference(
        tonight, last_night, std::back_inserter(added));
    return added;
}

#include <iostream>
#include <ranges>
#include <vector>

void print_recent_spikes(const std::vector<int>& samples, int threshold) {
    // Order of stages is the whole design. Reversing first makes "most
    // recent" the front of the pipeline, so take(3) stops the scan after
    // the third spike from the end -- iteration pulls one sample through
    // reverse, filter and take before touching the next one, and an
    // older history beyond that point is never examined.
    auto recent = samples
        | std::views::reverse
        | std::views::filter([threshold](int sample) {
              return sample > threshold;
          })
        | std::views::take(3);

    for (int sample : recent) {
        std::cout << sample << '\n';
    }
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <span>
#if __has_include(<execution>)
#  include <execution>
#endif

std::ptrdiff_t count_rejects(std::span<const std::uint32_t> status_codes) {
    // The predicate reads its argument and nothing else. Under any policy
    // the library may call it concurrently, in any order, and from any
    // thread; keeping a counter or a log line in here would be a data
    // race the caller owns, not something the library synchronises.
    const auto is_reject = [](std::uint32_t code) { return code >= 400; };

    // A policy is a permission, not a promise -- the implementation may
    // still run this sequentially. What it costs unconditionally is
    // scheduling overhead and any control over which cores run the work,
    // which is the wrong trade on a request path and a fine one for a
    // batch that reads a night of logs.
#if defined(__cpp_lib_parallel_algorithm)
    return std::count_if(std::execution::par,
                         status_codes.begin(), status_codes.end(),
                         is_reject);
#else
    return std::count_if(status_codes.begin(), status_codes.end(),
                         is_reject);
#endif
}
